"""Actual Python reader of the same per-ID board proof consumed by native.
This grants source qualification only, never source noise W, rank or sigma.
"""
from pathlib import Path
import hashlib,numpy as np
from .io_utils import read_json,read_jsonl
from .board_middle_append_v1 import checked,require,ref
from .r_inner_prefix_v1 import array
from .board_source_requalification import _support_contains
SCHEMA='rinkfit.current_native_board_source_qualification.v1'

def assert_current(manifest_path,packet_path,*,return_records=False):
 mf=Path(manifest_path).resolve();pp=Path(packet_path).resolve();c=read_json(mf);p=read_json(pp);seen=set();require(c['schema']==SCHEMA and c['source_packet']==ref(pp) and c['public_function']=='rinkfit_joint.board_native_qualification_v1.build' and 'source_math_source_authority'not in p,'Unknown native source issuer/current packet')
 for key in('issuer','current_source_guard','source_qualification','parent_packet','recipe'):checked(c[key],seen)
 gate=read_json(c['current_source_guard']['file']);require(gate['passed']and gate['packet']==c['source_packet'],'Actual current source gate differs');require(p['source_only_board_successor']['qualification']==c['source_qualification'] and p['source_only_board_successor']['parent_packet']==c['parent_packet'],'Actual source ancestry differs');recipe=read_json(c['recipe']['file']);require(recipe['schema']=='rinkfit.exact_board_middle_current_CPU_role_operator_recipe.v1' and recipe['device']=='cpu' and not recipe['frozen_visual_model_used'] and recipe['actual_RGB_replay']and recipe['old_query_and_UV_preserved'],'Actual source role/operator recipe differs')
 for d in c['actual_dependencies']+recipe['refs']:checked(d,seen)
 for frame in c['frames']:
  for key in('current_mask','source_frame_proof','actual_frame_manifest','exact_membership','recipe'):checked(frame[key],seen)
  receipt=frame['native_receipt'];src=read_json(frame['source_frame_proof'].get('file',frame['source_frame_proof'].get('path')));require(src['native_video_decode_receipt']==receipt and src['actual_native_RGB_sha256']==frame['actual_RGB_sha256']==receipt['decoded_native_RGB_sha256'] and receipt['source_video_sha256']==c['source_video_sha256'] and receipt['time_base']=='1/12800' and not receipt['native_RGB_resampled'],'Actual original native RGB/frame proof differs')
 arrays={k:array(p,k,pp.parent,seen)for k in p['arrays']};active=(arrays['admission']==1)&(arrays['fit_role']==1);ids=[i for i,rid in enumerate(p['source_row_ids'])if active[i]and rid.startswith(('board_instance_native/','board_instance/','outer_native/'))];queries={q['row_index']:q for q in p['queries']};a=c['actual_signed49'];samples=np.memmap(checked(a,seen),dtype='<f8',mode='r',shape=tuple(a['shape']));require(samples.shape==(len(ids),49) and len(ids)==c['count'],'Actual source-profile/active denominator differs');rows={}
 for k,r in enumerate(read_jsonl(checked(c['qualified_rows_native'],seen))):
  require(k<len(ids),'Extra source record');i=ids[k];uv=arrays['uv'][i];normal=arrays['profile_normal'][i];ph=r['physical_role_review'];op=r['original_operator_review'];ev=ph['actual_material_evidence'];frame=c['frames'][r['frame_index']];require(i>=c['old_raw_rows'] and r['global_row']==i and r['profile_row']==k and r['source_row_id']==p['source_row_ids'][i] and r['source_dataset_id']==p['source_dataset_ids'][i] and r['native_pts']==int(arrays['native_pts'][i])==frame['native_pts'] and r['shot_id']==p['shot_ids'][int(arrays['shot_index'][i])]==frame['shot_id'] and r['material_index']==int(arrays['material_index'][i]) and int(arrays['kind'][i])!=1,'Per-ID source clock/material differs')
  require(uv.tobytes()==np.asarray(r['current_uv'],dtype='<f8').tobytes() and normal.tobytes()==np.asarray(r['normal'],dtype='<f8').tobytes() and hashlib.sha256(uv.tobytes()).hexdigest()==r['UV_binary64_sha256'],'Original binary64 source UV/normal differs');require(ph['status']=='pass' and ph['source_row_id']==r['source_row_id'] and ph['native_pts']==r['native_pts'] and np.array_equal(ph['current_uv'],uv) and ph['source_recipe_sha256']==recipe['source_recipe_sha256'] and ph['source_pixels_unmodified'] and not ph['old_flags_or_model_navigation_used_as_identity']and not ph['unknown_physical_role_admitted'],'Actual original RGB role proof differs')
  role=r['physical_role'];label=p['material_binding']['materials'][r['material_index']]['label'];rel=ev['same_board_material_relation'];require(ph['material_role']==role and role in('board.top','board.contact')and label.startswith(role)and rel['top_entry_uv'][1]<rel['top_exit_uv'][1]<rel['yellow_entry_uv'][1]<=rel['first_iceward_fall_uv'][1]and not rel['competing_blue_platform'],'Actual material identity/order differs')
  if role=='board.top':require(ev['actual_blue_material_component']['coherent_thin_material_component']and ev['top_entry_transition']['observed']and ev['top_entry_transition']['source_material_values_are_nonreversing']and _support_contains(uv,ev['top_entry_transition']['actual_source_optical_interval_UV'],[0.,1.],xradius=12.),'Source mean not in actual entering-blue material support')
  else:require(ev['actual_selected_band_colour']['true_yellow_supported']and _support_contains(uv,ev['foot_fall_support_endpoints_uv'],ev['foot_profile_normal'],xradius=8.),'Source mean not in actual first-yellow-fall support')
  require(op['source_row_id']==r['source_row_id']and op['native_pts']==r['native_pts']and op['status']=='operator_pass'and op['physical_role_status']=='pass'and op['stored_49_sample_inner_peak_replay']and op['stored_profile_mean_replay_max_abs_px']==0 and r['actual_original_RGB_replay_max_abs_px']==0 and np.array_equal(op['stored_profile_replay_mu'],uv)and not op['original_peak_on_window_boundary']and not op['original_exact_flat_peak_intervals']and len(op['original_maximal_stationary_roots'])==1 and op['source_peak_signed_gradient']>0 and op['signed_blue_chroma_orientation_matches_physical_role']and op['original_selected_peak_inside_same_actual_transition'],'Actual original frozen49 operator differs')
  q=queries[i];offset=np.linspace(-3,3,49);alpha=float(r['alpha']);seed=np.asarray(r['seed_uv']);require(r['channel']==2 and r['polarity']==1 and np.array_equal(q['alpha'],offset)and np.array_equal(r['normal_offsets'],offset)and np.max(abs(np.asarray(q['native_uv'])-seed-offset[:,None]*normal))<1e-9 and -3<alpha<3 and abs(alpha-op['source_peak_offset'])<1e-9 and np.max(abs(seed+alpha*normal-uv))<1e-9 and abs(np.linalg.norm(normal)-1)<1e-9,'Actual original49 finite Query/mean differs');require(np.isfinite(samples[k]).all() and hashlib.sha256(samples[k].tobytes()).hexdigest()==r['actual_profile_binary64_sha256'],'Actual49 binary64 profile differs');r=dict(r,actual_native_RGB_sha256=frame['actual_RGB_sha256'],actual_frame=frame,actual_profile_values=samples[k]);rows[i]=r
 require(len(rows)==len(ids),'Missing per-ID qualification');report=dict(passed=True,manifest=ref(mf),packet=ref(pp),qualified_rows=len(rows),all_ID_UV_nativeRGB_mask_role_operator_and49Query_verified=True,source_noise_W_or_rank_issued=False,quality_accepted=False)
 return dict(report=report,records_by_global_row=rows,frames=c['frames'],profile_values=samples)if return_records else report
